'use strict';

var basePlot = require( './../lib' );
var str;
var opt = {
	'plotAreaHeight': 12,
	'plotAreaWidth': 102,
	'axisTicsLabels': [ [1, 10], [ 1, 2 ], [ 2, 66, 666, 666 ], [ 9666, 55, 5 ] ],
	'labelFormate': [ '%s', '%s', '%s', '%s' ],
	'zAxis': false,
	'wAxis': false,
	'backgroundColor': 'Bwhite',
	'foregroundColor': 'Fblack',
	'xTicsLabelSpace': 2,
	'yTicsLabelSpace': 1,
	'zTicsLabelSpace': 3,
	'wTicsLabelSpace': 4,
	'xAxisPos': 40,
	'yAxisPos': 5,
	'zAxisPos': 101,
	'xTicsSpacing': 9,
	'yTicsSpacing': 9,
	'zTicsSpacing': 9,
	'wTicsSpacing': 9,
	'wAxisPos': 11
};
var instance = basePlot( opt );
instance.initialize();
str = instance.render();
console.log( str );

// Adding string

// Note : as you can see 'hel' is on one side and remaining text is on other side this is because of the label space and we are adding the string as a safe area mode
instance.setString({
	'row': 4,
	'column': 37,
	'value': 'hello Stdlib!',
	'foregroundColor': 'Fwhite',
	'backgroundColor': 'Bgray',
	'safeArea': true
});

// Note : in Safe area mode we have to provide the coordinates in range of the plotAreaHeight and plotAreaWidth.
instance.setString({
	'row': 5,
	'column': 37,
	'value': 'hello Stdlib!',
	'foregroundColor': 'Fwhite',
	'backgroundColor': 'Bgray',
	'safeArea': true
});

// Now it is going to be Visible
instance.ticsLabelsBckColor = 'Bblue';
str = instance.render();
console.log( str );

// Adding bar in safe area
instance.setBar({
	'startPos': [ 0, 12 ],
	'height': 7,
	'width': 2,
	'safeArea': true,
	'overWrite': true,
	'glyph': 'block',
	'foregroundColor': 'Fred'
});
str = instance.render();
console.log( str );

// Adding bar without safe area mode
instance.setBar({
	'startPos': [ 0, 16 ],
	'height': 7,
	'width': 2,
	'overwrite': true,
	'safeArea': false,
	'glyph': 'block',
	'foregroundColor': 'Fred'
});
str = instance.render();
console.log( str );
